import openpyxl

# Load the embedded Excel file
wb = openpyxl.load_workbook('/root/input_extracted/ppt/embeddings/Microsoft_Excel_Worksheet.xlsx')
ws = wb.active

print("Excel Table Contents:")
print("=" * 60)
for row in ws.iter_rows():
    row_data = []
    for cell in row:
        if cell.value is not None:
            # Check if cell has a formula
            if hasattr(cell, 'data_type') and cell.data_type == 'f':
                row_data.append(f"{cell.value} [FORMULA]")
            else:
                row_data.append(str(cell.value))
        else:
            row_data.append("")
    if any(row_data):
        print(" | ".join(row_data))
EOF
